import pandas as pd


def run(inputs: dict) -> dict:
    target_snapshot = inputs["target_snapshot"].copy()
    cdc_events = inputs["cdc_events"].copy()
    watermark = inputs["watermark"].copy()

    # --- normalize dtypes ---
    if not target_snapshot.empty:
        target_snapshot["status_ts"] = pd.to_datetime(target_snapshot["status_ts"])
    if not cdc_events.empty:
        cdc_events["event_ts"] = pd.to_datetime(cdc_events["event_ts"])

    high_ts = watermark["high_ts"].iloc[0]
    high_ts = pd.to_datetime(high_ts)

    # --- build initial state from target_snapshot (assumed one row per user_id) ---
    state = {}
    for _, row in target_snapshot.iterrows():
        state[row["user_id"]] = {
            "email": row["email"],
            "status": row["status"],
            "status_ts": row["status_ts"],
        }

    # --- filter events strictly after watermark ---
    if not cdc_events.empty:
        new_events = cdc_events[cdc_events["event_ts"] > high_ts].copy()
    else:
        new_events = cdc_events.copy()

    # --- deterministic sequential ordering: (event_ts, event_seq) ascending ---
    if not new_events.empty:
        new_events = new_events.sort_values(
            by=["event_ts", "event_seq"], ascending=[True, True], kind="mergesort"
        )

        for _, ev in new_events.iterrows():
            uid = ev["user_id"]
            op = ev["op"]
            ts = ev["event_ts"]
            ev_email = ev["email"]

            cur = state.get(uid)

            if op == "D":
                if cur is None:
                    # no prior row; create soft-deleted row using event's email
                    state[uid] = {
                        "email": ev_email,
                        "status": "DELETED",
                        "status_ts": ts,
                    }
                else:
                    # preserve email as of deletion
                    state[uid] = {
                        "email": cur["email"],
                        "status": "DELETED",
                        "status_ts": ts,
                    }
            elif op == "U":
                if cur is None or cur["status"] == "ACTIVE":
                    state[uid] = {
                        "email": ev_email,
                        "status": "ACTIVE",
                        "status_ts": ts,
                    }
                else:
                    # cur status == 'DELETED'
                    deletion_ts = cur["status_ts"]
                    if ts > deletion_ts + pd.Timedelta(days=7):
                        # resurrection
                        state[uid] = {
                            "email": ev_email,
                            "status": "ACTIVE",
                            "status_ts": ts,
                        }
                    # else: discard update, state unchanged

    # --- build output dataframe ---
    records = []
    for uid, s in state.items():
        records.append(
            {
                "user_id": uid,
                "email": s["email"],
                "status": s["status"],
                "status_ts": s["status_ts"],
            }
        )

    new_snapshot = pd.DataFrame(
        records, columns=["user_id", "email", "status", "status_ts"]
    )

    return {"new_snapshot": new_snapshot}
